python3 - <<'PY'
import subprocess
words = [
    'equipment','information','rice','money','species','series','fish','sheep','jeans','police',
    'news','xnews','newss','analysis','analyses','crisis','crises','oxen','octopi','viri',
    'mice','lice','data','media','criteria','phenomena','cats','CATS','bus','gas','this','status','axis','alias','dog','men','people','children','teeth','geese'
]
UNC=set(words[:10])
def model(w):
    if w in UNC or w.endswith('news') or w in {'analysis','crisis'}:
        return 0
    if w.endswith('s'):
        return 1
    if w.endswith('octopi') or w.endswith('viri'):
        return 1
    if w in {'mice','lice','oxen'}:
        return 1
    # Rails /([ti])a$/ permits optional char before final ta/ia
    if len(w)>=2 and w[-2:] in {'ta','ia'}:
        return 1
    return 0
bad=[]
for w in words:
    p=subprocess.run(['/workspace/dataset/test15_executable',w],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    lines=p.stdout.splitlines()
    got=int(lines[-3])
    exp=model(w)
    if got!=exp: bad.append((w,got,exp,lines))
print(f'checked={len(words)} mismatches={len(bad)}')
for row in bad: print(row)
PY

